<script setup>
import { ref, onUnmounted } from 'vue'
import { FileSearch, Check, Clock3, Play, RotateCcw, Activity, Download } from 'lucide-vue-next'
const running=ref(false), done=ref(false), progress=ref(0), stageIndex=ref(0)
const stages=['语料抽取','向量知识库构建','结果消解']
let timer, tick=0
const startJob=()=>{clearInterval(timer);done.value=false;running.value=true;progress.value=0;stageIndex.value=0;tick=0;timer=setInterval(()=>{tick++;stageIndex.value=progress.value<30?0:progress.value<78?1:2;const base=stageIndex.value===0?0.22:stageIndex.value===1?0.13:0.20;const fluctuation=tick%17<5?0.52:tick%11<3?1.5:1;progress.value=Math.min(100,progress.value+base*fluctuation);if(progress.value>=100){clearInterval(timer);running.value=false;done.value=true}},1000)}
onUnmounted(()=>clearInterval(timer))
</script>
<template>
          <div class="process-layout"><section class="panel process-panel"><div class="panel-heading"><div><h2>创建语料处理任务</h2><p>配置数据来源，依次完成抽取、向量化和结果消解</p></div><span class="badge demo-badge">演示环境</span></div><div class="form-label">任务名称</div><input class="text-input" value="广西—东盟关键矿产语料处理"/><div class="form-label source-label">语料来源</div><div class="source-select"><div class="source-type"><FileSearch :size="17"/><span><strong>公开资料与案例语料</strong><small>广西自然资源厅 · ASEAN 矿产报告 · 企业演示需求</small></span><Check :size="16"/></div><div class="source-count">已选择 <b>30</b> 份材料 <span>约 8.6 MB</span></div></div><div class="form-label mode-label">处理流程</div><div class="pipeline"><div class="pipeline-step" :class="{current:running&&stageIndex===0, complete:done||stageIndex>0&&running}"><div class="step-num">01</div><div><strong>语料抽取</strong><span>实体、属性与关系识别</span></div><Check v-if="done||running&&stageIndex>0" class="step-check" :size="16"/></div><div class="pipeline-connector"></div><div class="pipeline-step" :class="{current:running&&stageIndex===1, complete:done||running&&stageIndex>1}"><div class="step-num">02</div><div><strong>向量知识库构建</strong><span>切片、嵌入与索引生成</span></div><Check v-if="done||running&&stageIndex>1" class="step-check" :size="16"/></div><div class="pipeline-connector"></div><div class="pipeline-step" :class="{current:running&&stageIndex===2, complete:done}"><div class="step-num">03</div><div><strong>结果消解</strong><span>实体去重、关系校验与可用性判断</span></div><Check v-if="done" class="step-check" :size="16"/></div></div><div class="run-foot"><span><Clock3 :size="14"/>预计耗时约 <b>10 分钟</b><i>演示任务按阶段模拟耗时</i></span><button class="button primary" :disabled="running" @click="startJob"><Play :size="14"/>{{running?'处理中…':done?'再次运行':'开始处理'}}</button></div></section><section class="panel progress-panel"><div class="panel-heading"><div><h2>任务进度</h2><p>处理状态与结果摘要</p></div><button class="icon-btn" @click="done=false;progress=0"><RotateCcw :size="16"/></button></div><div v-if="!running&&!done" class="empty-progress"><div class="empty-icon"><Activity :size="23"/></div><strong>等待开始</strong><span>启动任务后，这里将显示实时进度与预计剩余时间。</span></div><div v-else><div class="progress-meta"><strong>{{done?'处理完成':stages[stageIndex]}}</strong><span>{{done?'已完成':'预计剩余 '+Math.max(1,Math.ceil((100-progress)*0.10))+' 分钟'}}</span></div><div class="progress-track"><i :style="{width:progress+'%'}"></i></div><div class="progress-numbers"><b>{{Math.floor(progress)}}%</b><span>{{done?'任务已完成':`正在执行第 ${stageIndex+1} / 3 阶段`}}</span></div><div class="log-list"><div class="log-entry" :class="{dim:progress<20}"><span class="log-mark"><Check :size="12"/></span><span>已读取 30 份案例语料</span><time>09:42:01</time></div><div class="log-entry" :class="{dim:progress<45}"><span class="log-mark"><Check :size="12"/></span><span>抽取实体 146 个，关系 218 条</span><time>09:42:18</time></div><div class="log-entry" :class="{dim:progress<80}"><span class="log-mark"><Check :size="12"/></span><span>向量索引生成完成</span><time>09:42:36</time></div><div class="log-entry" :class="{dim:!done}"><span class="log-mark"><Check :size="12"/></span><span>消解通过，可用语料 93.2%</span><time>09:42:49</time></div></div><div v-if="done" class="result-callout"><Check :size="15"/><span><b>结果已就绪</b> · 136 个实体、203 条关系可用于图谱和匹配</span></div></div></section></div>
          <section v-if="done" class="panel result-table"><div class="panel-heading"><div><h2>消解结果</h2><p>判定语料的可用性与抽取质量</p></div><button class="button secondary"><Download :size="14"/>导出结果</button></div><div class="result-stats"><div><span>可用语料</span><b>28 <small>/ 30 份</small></b></div><div><span>识别实体</span><b>146 <small>个</small></b></div><div><span>知识关系</span><b>218 <small>条</small></b></div><div><span>消歧准确率</span><b>93.2<small>%</small></b></div></div></section>
          <div class="source-note">演示说明：进度条按真实任务阶段展示，当前页面为交互演示，将在数秒内加速完成；实际生产处理预计 5–15 分钟，耗时随语料规模与模型配置变化。任务结果为案例数据。</div>
</template>
